// Copy each variant's built output into the test suite as a checked-in
// fixture: src/__tests__/fixtures/bundler-matrix/<variant>/. The lab is the
// generator; the suite deploys the artifacts without installing a single
// bundler. Source maps, node_modules (tsc-unbundled's symlink is recreated
// by the test) and .forge-sim state are left out. Re-run after `run.mjs`
// whenever a variant's build config changes.
import { cp, rm, mkdir, readdir, stat, writeFile, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const lab = path.dirname(fileURLToPath(import.meta.url));
const dest = path.resolve(lab, '..', '..', 'src', '__tests__', 'fixtures', 'bundler-matrix');
const VARIANTS = ['forge-webpack', 'rspack', 'vite', 'rollup', 'parcel', 'esbuild-user', 'tsc-unbundled'];
const SKIP = (src) => /\.map$/.test(src) || /\/node_modules(\/|$)/.test(src) || /\/\.forge-sim(\/|$)/.test(src);

const only = process.argv.slice(2);
for (const v of only.length ? VARIANTS.filter((x) => only.includes(x)) : VARIANTS) {
  const from = path.join(lab, 'build', v);
  try { await stat(path.join(from, 'manifest.yml')); } catch { console.log(`skip ${v}: no build (run run.mjs first)`); continue; }
  const to = path.join(dest, v);
  await rm(to, { recursive: true, force: true });
  await mkdir(to, { recursive: true });
  for (const entry of await readdir(from)) {
    if (SKIP(path.join(from, entry))) continue;
    await cp(path.join(from, entry), path.join(to, entry), { recursive: true, filter: (s) => !SKIP(s) });
  }
  // The .map files are not copied, so drop the comments that point at them —
  // otherwise every import under vitest logs a failed source-map read.
  for (const file of await readdir(to, { recursive: true })) {
    if (!file.endsWith('.js')) continue;
    const f = path.join(to, file);
    const code = await readFile(f, 'utf8');
    const stripped = code.replace(/^\/\/[#@] sourceMappingURL=(?!data:).*$\n?/gm, '');
    if (stripped !== code) await writeFile(f, stripped);
  }
  console.log(`exported ${v}`);
}
await writeFile(path.join(dest, 'README.md'), `# bundler-matrix fixtures

Generated by \`lab/bundler-matrix/export-fixtures.mjs\` from the lab's builds —
do not hand-edit. Each directory is one bundler's output for the same tiny
Forge app (\`lab/bundler-matrix/app/src\`), laid out as a manual-packaged app:
\`manifest.yml\`, \`package.json\`, \`out/\` (backend), \`frontend/\` (single-entry
UI Kit) and, where the bundler built one, \`frontend-multi/\` (home/settings).
Deployed and rendered by \`bundler-matrix-fixtures.test.ts\`.

Regenerate: \`cd lab/bundler-matrix && npm install && node --import ../../dist/loader/register.js run.mjs && node export-fixtures.mjs\`.
`);
console.log('wrote README');
